/* Same-origin auth adapter. Credentials are never stored by this client. */
const form=document.querySelector('#auth-form');
for(const toggle of document.querySelectorAll('.password-toggle')){const input=document.getElementById(toggle.getAttribute('aria-controls'));input.dataset.password='true';toggle.onclick=()=>{input.type=input.type==='password'?'text':'password';toggle.textContent=input.type==='password'?'Show':'Hide';toggle.setAttribute('aria-pressed',String(input.type==='text'))}}
form.addEventListener('submit',async event=>{event.preventDefault();const status=document.querySelector('.auth-status'),button=form.querySelector('[type=submit]');status.hidden=false;status.textContent='';const name=form.querySelector('#artist-name');if(name&&!name.value.trim()){name.setCustomValidity('Enter your artist name.');name.reportValidity();return}button.disabled=true;const mode=form.dataset.mode;try{const response=await fetch('/api/auth/'+mode,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(Object.fromEntries(new FormData(form)))});if(!response.headers.get('content-type')?.includes('application/json'))throw Error('Account services are temporarily unavailable. Please try again.');const result=await response.json();if(!response.ok){if(mode==='signin'&&response.status===403){sessionStorage.setItem('uniify-pending-email',form.elements.email.value);location.href='/verify-email';return;}throw Error(result.error||'Unable to continue. Please try again.');}if(mode==='signup'){sessionStorage.setItem('uniify-pending-email',form.elements.email.value);sessionStorage.setItem('uniify-pending-name',name.value.trim());location.href='/verify-email'}else if(mode==='signin'){location.href=result.onboarded?'/workspace':'/onboarding'}else {sessionStorage.setItem('uniify-reset-email',form.elements.email.value);location.href='/reset-password'}}catch(error){status.textContent=error.message;status.focus()}finally{button.disabled=false;if(form.elements.password)form.elements.password.value=''}});
form.addEventListener('input',()=>form.querySelector('#artist-name')?.setCustomValidity(''));
